import { useCallback, useState } from 'react';
import { Button, Dialog } from '@jinx-ui/react';

type DeleteProjectButtonProps = {
  onConfirm: () => void;
  projectName?: string;
};

export default function DeleteProjectButton({ onConfirm, projectName }: DeleteProjectButtonProps) {
  const [open, setOpen] = useState(false);

  const close = useCallback(() => setOpen(false), []);

  const confirm = useCallback(() => {
    setOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button variant="danger" onClick={() => setOpen(true)}>
        Удалить проект
      </Button>

      <Dialog
        open={open}
        onClose={close}
        title="Удалить проект?"
        aria-describedby="jx-delete-project-description"
      >
        <p
          id="jx-delete-project-description"
          className="jx-text"
          style={{ margin: 0, color: 'var(--jx-color-text-muted)' }}
        >
          {projectName
            ? `Проект «${projectName}» будет удалён навсегда. Действие необратимо.`
            : 'Проект будет удалён навсегда. Действие необратимо.'}
        </p>

        <div
          className="jx-stack jx-stack--horizontal"
          style={{
            display: 'flex',
            justifyContent: 'flex-end',
            gap: 'var(--jx-space-2)',
            marginTop: 'var(--jx-space-4)',
          }}
        >
          <Button variant="ghost" onClick={close}>
            Отмена
          </Button>
          <Button variant="danger" onClick={confirm} autoFocus>
            Удалить
          </Button>
        </div>
      </Dialog>
    </>
  );
}

